package org.brightstats.stats;

import java.util.*;
import org.apache.commons.math3.linear.*;

/** Adaptive component-wise random-walk Metropolis; adaptation stops after warmup. */
public final class BayesianSem {
    private BayesianSem(){}
    public enum Family { NORMAL, LOG_NORMAL }
    public record Prior(String parameter,Family family,double location,double scale){public Prior{if(parameter==null||parameter.isBlank()||family==null||!Double.isFinite(location)||!(scale>0)||!Double.isFinite(scale))throw new IllegalArgumentException("Every parameter needs an explicit proper Normal or Log-normal prior; scale must be positive.");}}
    public record Options(List<Prior> priors,int chains,int warmup,int draws,long seed,double confidence,int predictiveDraws){public Options{priors=List.copyOf(priors);Inference.confidence(confidence);if(priors.isEmpty()||new HashSet<>(priors.stream().map(Prior::parameter).toList()).size()!=priors.size()||chains<2||chains>4||warmup<200||warmup>5000||draws<200||draws>5000||predictiveDraws<20||predictiveDraws>200||(long)chains*draws*priors.size()>200000||(long)chains*(warmup+draws)*priors.size()>1000000)throw new IllegalArgumentException("Choose 2–4 chains, 200–5,000 warmup/retained draws, 20–200 predictive draws, at most 200,000 stored parameter draws and one million proposals.");}}
    public record Chain(int index,long seed,double[][] draws,double[] logPosteriorUpToConstant,double[] samplingAcceptance,double[] finalProposalScales,int invalidProposals,int priorInitializationAttempts){public Chain{draws=Matrices.copy(draws);logPosteriorUpToConstant=logPosteriorUpToConstant.clone();samplingAcceptance=samplingAcceptance.clone();finalProposalScales=finalProposalScales.clone();}@Override public double[][] draws(){return Matrices.copy(draws);}@Override public double[] logPosteriorUpToConstant(){return logPosteriorUpToConstant.clone();}@Override public double[] samplingAcceptance(){return samplingAcceptance.clone();}@Override public double[] finalProposalScales(){return finalProposalScales.clone();}}
    public record Term(String parameter,McmcDiagnostics.Summary posterior,double posteriorProbabilityPositive){}
    public record PredictiveDraw(int index,String source,double[] parameterValues,double observedMahalanobis,double replicatedMahalanobis,double[] replicatedMeans,double[] replicatedStandardDeviations){public PredictiveDraw{parameterValues=parameterValues.clone();replicatedMeans=replicatedMeans.clone();replicatedStandardDeviations=replicatedStandardDeviations.clone();}@Override public double[] parameterValues(){return parameterValues.clone();}@Override public double[] replicatedMeans(){return replicatedMeans.clone();}@Override public double[] replicatedStandardDeviations(){return replicatedStandardDeviations.clone();}}
    public record Predictive(List<String> variables,double[] observedMeans,double[] observedStandardDeviations,List<PredictiveDraw> prior,List<PredictiveDraw> posterior,int priorDrawAttempts,double priorReplicatedDiscrepancyExceedance,double posteriorReplicatedDiscrepancyExceedance){public Predictive{variables=List.copyOf(variables);observedMeans=observedMeans.clone();observedStandardDeviations=observedStandardDeviations.clone();prior=List.copyOf(prior);posterior=List.copyOf(posterior);}@Override public double[] observedMeans(){return observedMeans.clone();}@Override public double[] observedStandardDeviations(){return observedStandardDeviations.clone();}}
    public record Fit(SemModel.Model model,Options options,int suppliedRows,int informativeRows,int emptyRows,String sampler,boolean diagnosticsPassed,List<Term> terms,List<Chain> chains,Predictive predictive,List<String> warnings){public Fit{terms=List.copyOf(terms);chains=List.copyOf(chains);warnings=List.copyOf(warnings);}}
    static final class Posterior {
        final SemObservedLikelihood likelihood;final SemModel.Model model;final List<Prior> priors;final double[] low,high;
        Posterior(double[][] data,SemModel.Model model,Options options){this.model=model;likelihood=new SemObservedLikelihood(data,model);Map<String,Prior> named=new HashMap<>();options.priors().forEach(p->named.put(p.parameter(),p));if(named.size()!=model.parameters().size()||model.parameters().stream().anyMatch(p->!named.containsKey(p.name())))throw new IllegalArgumentException("Declare exactly one prior for every free model parameter, with no extra names.");priors=model.parameters().stream().map(p->named.get(p.name())).toList();low=RamMoments.lower(model);high=RamMoments.upper(model);}
        double[] theta(double[] coordinates){double[] theta=new double[coordinates.length];for(int j=0;j<theta.length;j++)theta[j]=priors.get(j).family()==Family.LOG_NORMAL?Math.exp(coordinates[j])/model.parameters().get(j).scale():coordinates[j];return theta;}
        double logDensity(double[] coordinates){double[] theta=theta(coordinates);double prior=0;for(int j=0;j<theta.length;j++){if(!Double.isFinite(theta[j])||theta[j]<low[j]||theta[j]>high[j])return Double.NEGATIVE_INFINITY;var p=priors.get(j);double raw=theta[j]*model.parameters().get(j).scale(),value=p.family()==Family.LOG_NORMAL?Math.log(raw):raw,z=(value-p.location())/p.scale();prior+=-.5*z*z-Math.log(p.scale())-.5*Math.log(2*Math.PI)+(p.family()==Family.LOG_NORMAL?0:Math.log(model.parameters().get(j).scale()));}double likelihoodValue=likelihood.evaluate(theta).value();return Double.isFinite(likelihoodValue)&&Double.isFinite(prior)?prior-likelihood.observations*likelihoodValue:Double.NEGATIVE_INFINITY;}
        double[] prior(Random rng,int[] attempts){for(int trial=0;trial<10000;trial++){Matrices.interrupted();attempts[0]++;double[] coordinates=new double[priors.size()];for(int j=0;j<coordinates.length;j++){var prior=priors.get(j);double value=prior.location()+prior.scale()*rng.nextGaussian();coordinates[j]=prior.family()==Family.LOG_NORMAL?value:value/model.parameters().get(j).scale();}if(Double.isFinite(logDensity(coordinates)))return coordinates;}throw new IllegalArgumentException("Could not draw an admissible prior state in 10,000 attempts. Review priors, bounds and RAM identification; no silent prior repair was applied.");}
    }
    public static Fit fit(double[][] data,SemModel.Model model,Options options,java.util.function.IntConsumer progress){
        if(model.parameters().isEmpty()||model.parameters().size()>24||model.variables().size()>48||model.observed().length>16||data.length>5000)throw new IllegalArgumentException("Native random-walk Bayesian SEM supports 1–24 free parameters, 16 observed/48 total variables and at most 5,000 supplied rows.");var posterior=new Posterior(data,model,options);int q=model.parameters().size(),completed=0;List<Chain> chains=new ArrayList<>();
        for(int c=0;c<options.chains();c++){
            long seed=mix(options.seed()+0x9e3779b97f4a7c15L*(c+1));Random rng=new Random(seed);int[] attempts={0};double[] coordinates=posterior.prior(rng,attempts);double current=posterior.logDensity(coordinates);double[] logStep=new double[q],accepted=new double[q];for(int j=0;j<q;j++){var prior=posterior.priors.get(j);double scale=prior.family()==Family.LOG_NORMAL?prior.scale():prior.scale()/model.parameters().get(j).scale();logStep[j]=Math.log(Math.max(1e-8,Math.min(100,scale*.25)));}double[][] draws=new double[options.draws()][q];double[] density=new double[options.draws()];int invalid=0;
            for(int iteration=0;iteration<options.warmup()+options.draws();iteration++){
                Matrices.interrupted();for(int j=0;j<q;j++){double[] candidate=coordinates.clone();candidate[j]+=Math.exp(logStep[j])*rng.nextGaussian();double next=posterior.logDensity(candidate);boolean usable=Double.isFinite(next);if(!usable)invalid++;boolean accept=usable&&Math.log(rng.nextDouble())<next-current;if(accept){coordinates=candidate;current=next;}if(iteration<options.warmup())logStep[j]=Math.max(-18,Math.min(4.6,logStep[j]+((accept?1:0)-.44)/Math.sqrt(iteration+10)));else if(accept)accepted[j]++;}
                if(iteration>=options.warmup()){int index=iteration-options.warmup();draws[index]=posterior.theta(coordinates);for(int j=0;j<q;j++)draws[index][j]*=model.parameters().get(j).scale();density[index]=current;}completed++;if(progress!=null)progress.accept(completed);
            }
            double[] steps=new double[q];for(int j=0;j<q;j++){steps[j]=Math.exp(logStep[j]);accepted[j]/=options.draws();}chains.add(new Chain(c+1,seed,draws,density,accepted,steps,invalid,attempts[0]));
        }
        List<Term> terms=new ArrayList<>();boolean passed=true;for(int j=0;j<q;j++){double[][] values=new double[chains.size()][options.draws()];int positive=0;for(int c=0;c<chains.size();c++)for(int i=0;i<options.draws();i++){values[c][i]=chains.get(c).draws[i][j];if(values[c][i]>0)positive++;}var summary=McmcDiagnostics.summarize(values,options.confidence());passed&=Double.isFinite(summary.rankSplitRhat())&&summary.rankSplitRhat()<1.01&&summary.bulkEffectiveSampleSize()>=100*options.chains()&&summary.tailEffectiveSampleSize()>=100*options.chains();terms.add(new Term(model.parameters().get(j).name(),summary,positive/(double)(options.chains()*options.draws())));}
        Predictive predictive=predictive(data,posterior,chains,options);List<String> warnings=new ArrayList<>();warnings.add("Sampler is adaptive component-wise random-walk Metropolis, not HMC/NUTS. Each independent chain initializes from the joint proper prior restricted by configured bounds and admissible RAM states. Warmup alone adapts proposal scales; retained sampling is fixed-kernel, unthinned and seeded. Slow mixing is possible in strongly correlated/high-dimensional SEM.");warnings.add("Normal prior location/scale are raw-unit mean/SD; Log-normal location/scale are log-unit mean/SD. Log-normal proposals operate on log(raw parameter) and include the change-of-variables Jacobian. Independent declared priors are jointly conditioned on RAM admissibility and bounds. Their unknown joint truncation normalizer is constant in parameters; log density is up to a constant, not model evidence.");warnings.add("Rank/folded split R-hat, bulk/tail ESS and raw-mean ESS/MCSE are finite-chain screens, not proof of convergence or identification. The pass screen requires R-hat <1.01 and bulk/tail ESS ≥100 per original chain for every parameter. Posterior probability positive is not a frequentist P value.");warnings.add("Prior/posterior predictive replications preserve the original observed/missing mask and compare an observed-pattern Mahalanobis discrepancy plus variable mean/SD distributions. Exceedance fractions are predictive diagnostics, not uniform calibrated P values. Gaussian ignorable missingness assumptions remain; this is not ordinal, MNAR or multilevel Bayesian estimation.");if(!passed)warnings.add("At least one convergence/ESS screen failed. Posterior summaries remain provisional; increase draws, improve priors/parameterization or use a more suitable sampler before substantive interpretation.");for(var chain:chains)if(Arrays.stream(chain.samplingAcceptance).anyMatch(x->x<.1||x>.8))warnings.add("Chain "+chain.index()+" has very low/high component acceptance; inspect traces and proposal scales.");return new Fit(model,options,data.length,posterior.likelihood.observations,posterior.likelihood.emptyRows,"ADAPTIVE_COMPONENT_RANDOM_WALK_METROPOLIS",passed,terms,chains,predictive,warnings);
    }
    static Predictive predictive(double[][] data,Posterior posterior,List<Chain> chains,Options options){Random rng=new Random(mix(options.seed()^0x44b7351d1a7c903fL));List<PredictiveDraw> prior=new ArrayList<>(),post=new ArrayList<>();int[] attempts={0};int count=options.predictiveDraws();for(int i=0;i<count;i++){Matrices.interrupted();double[] theta=posterior.theta(posterior.prior(rng,attempts));prior.add(replicate(data,posterior.model,theta,rng,i+1,"Prior"));int flattened=(int)((long)i*chains.size()*options.draws()/count),c=flattened/options.draws(),draw=flattened%options.draws();double[] raw=chains.get(c).draws[draw],point=raw.clone();for(int j=0;j<point.length;j++)point[j]/=posterior.model.parameters().get(j).scale();post.add(replicate(data,posterior.model,point,rng,i+1,"Posterior"));}double[][] observed=summary(data);return new Predictive(Arrays.stream(posterior.model.observed()).mapToObj(j->posterior.model.variables().get(j)).toList(),observed[0],observed[1],prior,post,attempts[0],prior.stream().filter(v->v.replicatedMahalanobis()>=v.observedMahalanobis()).count()/(double)count,post.stream().filter(v->v.replicatedMahalanobis()>=v.observedMahalanobis()).count()/(double)count);}
    static PredictiveDraw replicate(double[][] data,SemModel.Model model,double[] theta,Random rng,int index,String source){var state=RamMoments.state(model,theta);if(state==null)throw new IllegalArgumentException("Predictive state is inadmissible.");int p=model.observed().length;double[] scales=new double[p];double[][] correlation=state.covariance().getData();for(int j=0;j<p;j++)scales[j]=Math.sqrt(correlation[j][j]);for(int i=0;i<p;i++)for(int j=0;j<p;j++)correlation[i][j]=correlation[i][j]/scales[i]/scales[j];RealMatrix normalized=new Array2DRowRealMatrix(correlation);var cholesky=new CholeskyDecomposition(normalized,1e-8,1e-12);double[][] lowerValues=cholesky.getL().getData();for(int i=0;i<p;i++)for(int j=0;j<p;j++)lowerValues[i][j]*=scales[i];RealMatrix lower=new Array2DRowRealMatrix(lowerValues);double[][] replica=new double[data.length][p];Map<String,RealMatrix> inverse=new HashMap<>();double observed=0,replicated=0;for(int i=0;i<data.length;i++){Matrices.interrupted();double[] z=new double[p];for(int j=0;j<p;j++)z[j]=rng.nextGaussian();RealVector generated=lower.operate(new ArrayRealVector(z)).add(state.mean());for(int j=0;j<p;j++)replica[i][j]=Double.isFinite(data[i][j])?generated.getEntry(j):Double.NaN;final int row=i;int[] columns=java.util.stream.IntStream.range(0,p).filter(j->Double.isFinite(data[row][j])).toArray();if(columns.length==0)continue;RealMatrix weight=inverse.computeIfAbsent(Arrays.toString(columns),key->new CholeskyDecomposition(normalized.getSubMatrix(columns,columns),1e-8,1e-12).getSolver().getInverse());double[] a=new double[columns.length],b=new double[columns.length];for(int j=0;j<columns.length;j++){a[j]=(data[i][columns[j]]-state.mean().getEntry(columns[j]))/scales[columns[j]];b[j]=(replica[i][columns[j]]-state.mean().getEntry(columns[j]))/scales[columns[j]];}RealVector av=new ArrayRealVector(a),bv=new ArrayRealVector(b);observed+=av.dotProduct(weight.operate(av));replicated+=bv.dotProduct(weight.operate(bv));}double[][] summary=summary(replica);double[] raw=theta.clone();for(int j=0;j<raw.length;j++)raw[j]*=model.parameters().get(j).scale();return new PredictiveDraw(index,source,raw,observed,replicated,summary[0],summary[1]);}
    static double[][] summary(double[][] data){int p=data[0].length;double[] means=new double[p],ss=new double[p];int[] count=new int[p];for(var row:data)for(int j=0;j<p;j++)if(Double.isFinite(row[j])){count[j]++;double delta=row[j]-means[j];means[j]+=delta/count[j];ss[j]+=delta*(row[j]-means[j]);}for(int j=0;j<p;j++)ss[j]=count[j]>1?Math.sqrt(ss[j]/(count[j]-1)):Double.NaN;return new double[][]{means,ss};}
    private static long mix(long value){value=(value^(value>>>30))*0xbf58476d1ce4e5b9L;value=(value^(value>>>27))*0x94d049bb133111ebL;return value^(value>>>31);}
}
